import{_ as i,a,b as s,c as r,d as n,e as l,f as d,g as p,h as c,i as h,j as u,k as m,l as f}from"./chunks/Install17a.WxJn2Ju7.js";import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as y}from"./chunks/EN.P9aPnFBv.js";import{_ as b}from"./chunks/Install17.CwCXrGHM.js";import{_ as g,o as v,c as w,a3 as _}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"install/install.md","filePath":"install/install.md"}'),A={name:"install/install.md"};function k(T,e,E,I,S,x){return v(),w("div",null,[...e[0]||(e[0]=[_('<p>Once downloaded, install the xDrip apk.</p><img src="'+i+'" style="zoom:50%;"><p>On recent Android versions you will see a Google Play Protect warning that the app is unsafe, as it was built for older Android versions. Ignore it with More details, then Install anyway.</p><img src="'+a+'" style="zoom:50%;"><p><strong>You need to <a href="https://developer.android.com/distribute/marketing-tools/alternative-distribution#unknown-sources" target="_blank" rel="noreferrer">authorize installation of apps from unknown sources</a> in Android security settings.</strong><br> The official versions of xDrip are virus and malware free: being open source and controlled by the main developer makes its distribution safe if you download it from GitHub.</p><img src="'+s+'" style="zoom:50%;"><p>Touch <code>Settings</code> then enable <code>Allow from this source</code>.</p><img src="'+r+'" style="zoom:50%;"><p>Once installed, open xDrip.</p><img src="'+n+'" style="zoom:75%;"><h3 id="understand-what-is-xdrip" tabindex="-1">Understand what xDrip is <a class="header-anchor" href="#understand-what-is-xdrip" aria-label="Permalink to &quot;Understand what xDrip is {#understand-what-is-xdrip}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title"><strong>Read</strong> the important Warning</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+l+'" style="zoom:50%;"></p><img src="'+d+'" style="zoom:50%;"> Do NOT use or rely on this software or any associated materials for any medical purpose or decision. Do NOT rely on this system for any real-time alarms or time critical data. Do NOT use or rely on this system for treatment decisions or use as a substitute for professional healthcare judgement. All software and materials have been provided for informational purposes only as a proof of concept to assist possibilities for further research. No claims at all are made about fitness for any purpose and everything is provided **AS IS**. Any part of the system can fail at any time. Always seek the advice of a qualified healthcare professional for any medical questions. Always follow your glucose-sensor or other device manufacturers&#39; instructions when using any equipment; do not discontinue use of accompanying reader or receiver, other than as advised by your doctor. This software is not associated with or endorsed by any equipment manufacturer and all trademarks are those of their respective owners. Your use of this software is entirely at your own risk. No charge has been made by the developers for the use of this software. This is an open-source project which has been created by volunteers. The source code is published free and open-source for you to inspect and evaluate. By using this software and/or website you agree that you are over 18 years of age and have read, understood and agree to all of the above. </div><br><p><strong>Read</strong> the EULA.</p><div class="warning custom-block"><p class="custom-block-title">Make sure you fully understand it before saving.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+p+'" style="zoom:50%;"></p><p>xDrip MUST NOT BE USED TO MAKE MEDICAL DECISIONS.<br> IT IS A RESEARCH TOOL ONLY AND IS PROVIDED &quot;AS IS&quot; WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.<br> THE ENTIRE RISK AS TO THE QUALITY AND PERFORMANCE OF THE PROGRAM IS WITH YOU.<br> SHOULD THE PROGRAM PROVE DEFECTIVE, YOU ASSUME THE COST OF ALL NECESSARY SERVICING, REPAIR OR CORRECTION.</p></div><br><h3 id="authorize-background-activity" tabindex="-1">Authorize background activity <a class="header-anchor" href="#authorize-background-activity" aria-label="Permalink to &quot;Authorize background activity&quot;">​</a></h3><p>xDrip must have the right to run in background: it must be whitelisted from battery optimization. This is essential for correct functioning. It should ask you to allow this authorization. If it doesn&#39;t or you need to verify this later, you&#39;ll have to check it in your phone <code>Settings</code> - <code>Apps</code> - <code>xDrip</code>. Consult your phone manual as it will depend on Android version and manufacturer.</p><div class="admonition xdripitem"><p class="admonition-title">Please allow Permission</p><p> xDrip needs whitelisting for proper performance.</p><p>      <span style="background-color:white;color:black;"> OK </span></p></div><img src="'+c+'" style="zoom:75%;"><p><em>Note: With Android 12 and above you won&#39;t see <strong>whitelisting</strong> anymore.</em></p><p>More information <a href="./../troubleshoot/savings.html#apps-battery-savings">here</a>.</p><br><h3 id="authorize-notifications" tabindex="-1">Authorize notifications <a class="header-anchor" href="#authorize-notifications" aria-label="Permalink to &quot;Authorize notifications&quot;">​</a></h3><p>xDrip needs to access phone notifications to perform as expected.</p><img src="'+h+'" style="zoom:75%;"><br><h2 id="verify-which-version-is-installed" tabindex="-1">Verify which version is installed <a class="header-anchor" href="#verify-which-version-is-installed" aria-label="Permalink to &quot;Verify which version is installed&quot;">​</a></h2><p>Touch the back button on your phone until you&#39;re back to the main screen. Select the hamburger menu top left then <code>System Status</code>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p>  System Status</p></div><p>Current version will be displayed after <code>Version</code>. In the example below, January 28th 2022.</p><img src="'+u+'" style="zoom:75%;"><p>On most recent versions, you will find it on all system status pages.</p><img src="'+m+'" style="zoom:76%;"><p>See <a href="./../use/update.html">here</a> for upgrade or downgrade.</p><br><h2 id="make-sure-xdrip-will-not-be-put-to-sleep" tabindex="-1">Make sure xDrip will not be put to sleep <a class="header-anchor" href="#make-sure-xdrip-will-not-be-put-to-sleep" aria-label="Permalink to &quot;Make sure xDrip will not be put to sleep&quot;">​</a></h2><p>These settings are default, but still make sure they are exactly like shown below. Any time your phone updates, come back and check again: disable and enable checkboxes that should be enabled to enforce the settings.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Settings<br>  Less Common Settings<br>   Other misc. Options<br>    Collector in foreground</p></div><p>Since Android 7 support was retired (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12th Jul 2026</a>), the collector always runs in foreground on Android 8.0 and above — there is no longer a toggle for it. The persistent notification graph in your phone drop down curtain is essential to keep the app alive and is always shown.</p><div class="admonition xdripitem"><p class="admonition-title">Compact Persistent Notification <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Enable to hide the graph in the notification and display only the current glucose value.</p></div><p>If you&#39;d rather not show the graph in the persistent notification, enable <code>Compact Persistent Notification</code> to show just the current glucose value instead.</p><div class="admonition xdripitem"><p class="admonition-title">Battery Optimization prompt <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> On Android 6+ ensure battery optimization is switched off (recommended).</p></div><p><code>Battery optimization prompt</code> should be <strong>disabled</strong> as you should have agreed to <a href="#authorize-background-activity">battery whitelisting</a> during install. If not, whitelist xDrip from battery optimization in Android settings.</p><div class="admonition xdripitem"><p class="admonition-title">Wake workarounds <span class="symbol"><img src="'+y+'" style="zoom:75%;"></span></p><p> Use workarounds to avoid non-standard Android behavior of some handsets. Without this, collectors usually fail to get data.</p></div><p>Previously &quot;Samsung workaround&quot;, this option is a fix to non-compliance from some vendors to Android specifications. This option should enable automatically with some smartphones. Recommended.</p><h3 id="enable-location" tabindex="-1">Enable location <a class="header-anchor" href="#enable-location" aria-label="Permalink to &quot;Enable location&quot;">​</a></h3><p>For newer Android versions (6 and above), location is <a href="https://developer.android.com/training/location/permissions" target="_blank" rel="noreferrer">mandatory</a> to allow Bluetooth Low Energy connection.<br> If you will use xDrip with a Bluetooth sensor or bridge you <strong>must</strong> enable location (Android Settings -&gt; <a href="https://support.google.com/android/answer/3467281" target="_blank" rel="noreferrer">Location</a>) and authorize xDrip to access it. Consult your phone manual as it will depend on Android version and manufacturer.</p><p>Make sure to select All the time from settings.</p><img src="'+f+'" style="zoom:75%;"><img src="'+b+'" style="zoom:75%;"><br><p>Proceed to <a href="./datasource.html">data source selection</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.15" target="_blank" rel="noreferrer"><em>Last modified 18/7/2026</em></a></p>',57)])])}const q=g(A,[["render",k]]);export{C as __pageData,q as default};
